71: // Probe local proxy daemon
72: function checkServerHealth(port = 8088) {
73:   return new Promise((resolve) => {
74:     const req = http.get(`http://127.0.0.1:${port}/health`, { timeout: 1000 }, (res) => {
75:       let data = '';
76:       res.on('data', chunk => data += chunk);
77:       res.on('end', () => {
78:         try {
79:           const json = JSON.parse(data);
80:           resolve(json && json.status === 'ok');
81:         } catch (e) {
82:           resolve(false);
83:         }
84:       });
85:     });
86:     req.on('error', () => resolve(false));
87:     req.on('timeout', () => { req.destroy(); resolve(false); });
88:   });
89: }
